def mean_squared_error(predictions, targets):
    total = 0
    for p, t in zip(predictions, targets):
        total += (p - t) ** 2
    return total / len(predictions)

predictions = [2.5, 3.8, 4.1]
targets     = [3.0, 4.0, 4.0]

print(mean_squared_error(predictions, targets))  # 0.097
